onClick:
{{ (async()=>{ try {
  const raw = FilePickerIndividualAgreement.files || [];
  if (!raw.length) throw new Error('Select at least one paper agreement file.');
  const attachments = [];
  for (let i=0;i<raw.length;i++) {
    const file=raw[i];
    const encodedData=file?.data || file?.base64 || file?.content || file?.fileData || file?.file;
    if (!encodedData || typeof encodedData !== 'string') throw new Error('File "' + (file?.name || 'unknown') + '" does not contain Base64 upload data.');
    const res=await apiUploadIndividualEvidence.run({files:[{name:file.name,type:file.type || file.mimeType || 'application/octet-stream',size:file.size,data:encodedData}]});
    const value=res?.data ?? res;
    const arr=Array.isArray(value)?value:(Array.isArray(value?.files)?value.files:(value && typeof value==='object'?[value]:[]));
    const good=arr.filter(x=>x && (x.path || x.signedPath));
    if(!good.length) throw new Error('Upload succeeded but returned no attachment path for "' + file.name + '".');
    attachments.push(...good);
  }
  const rows=await qCreateIndividualPaperAgreement.run({evidence_json:JSON.stringify(attachments)});
  const row=Array.isArray(rows)?rows[0]:rows;
  if(!row?.member_agreement_id) throw new Error('Paper agreement was created but no member_agreement_id was returned.');
  await qIndividualMemberAgreements.run();
  resetWidget('FilePickerIndividualAgreement', true);
  resetWidget('inpIndividualAgreementReviewNotes', true);
  showAlert('Paper agreement uploaded and queued for review.','success');
} catch(e) {
  showAlert('Unable to upload paper agreement: ' + (e?.message || e),'error');
} })() }}
